import { asset_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoriesEddition: Boolean,
    categoriesItem: Object
  },
  data() {
    return {
      categoriesName: "",
      depreciationCode: "",
      categoriesdescription: "",
      date: "",
      modal: false,
      isverification: false,
      loading: false,
      depreciationitems: Array.from({
        length: 100
      }, (_, i) => i + 1)
    };
  },
  watch: {
    categoriesEddition: {
      async handler() {
        if (this.categoriesEddition == true) {
          this.date = !this.categoriesItem.category_verification_date || this.categoriesItem.category_verification_date == "N/A" ? "" : this.categoriesItem.category_verification_date;
          this.categoriesName = this.categoriesItem.category_name;
          this.categoriesdescription = this.categoriesItem.category_description;
          this.depreciationCode = this.categoriesItem.category_depriciation;
          this.isverification = this.categoriesItem.is_category_verification == null ? false : this.categoriesItem.is_category_verification;
        }
      },
      immediate: true
    }
  },
  computed: {
    computedDateFormatted() {
      return this.formatDate(this.date);
    },
    verficationdaterule() {
      return this.isverification ? [v => !!v || "Required"] : [];
    }
  },
  methods: {
    getcal() {
      this.modal = true;
    },
    formatDate(date) {
      if (!date) return null;
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_categories, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "UPDATE_CATEGORY",
            category_name: this.categoriesName,
            category_depriciation: Number(this.depreciationCode),
            category_id: this.categoriesItem.category_id,
            is_category_verification: this.isverification,
            category_verification_date: this.isverification ? this.date : "N/A",
            category_description: this.categoriesdescription
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.asset_categories);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "update");
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
